          ]
        },
        {
          "stage": "identity",
          "focus": "商品名称与基本定位",
          "sentences": [
            {
              "display_text": "今天看的这款是轻行可折叠通勤托特包，就是给日常出门准备的。",
              "spoken_text": "今天看的这款是轻行可折叠通勤托特包，就是给日常出门准备的。",
              "kind": "product_claim",
              "fact_ids": ["NAME"]
            },
            {
              "display_text": "它没有花哨的设计，重点放在背起来顺手、用起来简单。",
              "spoken_text": "它没有花哨的设计，重点放在背起来顺手、用起来简单。",
              "kind": "product_claim",
              "fact_ids": ["NAME", "SELLING"]
