          ]
        },
        {
          "stage": "benefit",
          "focus": "长肩带与手提单肩两种携带方式",
          "sentences": [
            {
              "display_text": "先看这根长肩带，它让这只包可以手提，也可以单肩背着。",
              "spoken_text": "先看这根长肩带，它让这只包可以手提，也可以单肩背着。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "比如早上买早餐，你可以单肩背着，两只手拿豆浆和零钱。",
              "spoken_text": "比如早上买早餐，你可以单肩背着，两只手拿豆浆和零钱。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "到了办公室，不想背了，把肩带一收，手提去会议室也行。",
              "spoken_text": "到了办公室，不想背了，把肩带一收，手提去会议室也行。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
          ]
        },
        {
          "stage": "benefit",
          "focus": "主袋拉链开合与内部小口袋",
          "sentences": [
            {
              "display_text": "主袋是拉链开合的，东西放进去，拉上拉链再走。",
              "spoken_text": "主袋是拉链开合的，东西放进去，拉上拉链再走。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "里面还有一个小口袋，钥匙、门禁卡这类小东西可以单独放。",
              "spoken_text": "里面还有一个小口袋，钥匙、门禁卡这类小东西可以单独放。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            },
            {
              "display_text": "下班回家，不用把整个包倒过来找钥匙，伸手往小口袋里一摸就行。",
              "spoken_text": "下班回家，不用把整个包倒过来找钥匙，伸手往小口袋里一摸就行。",
              "kind": "product_claim",
              "fact_ids": ["SELLING"]
            }
          ]
